    colorDiff += distance(tag, GetTagValue(fragUV, vec2<f32>( 0, -t)));
    colorDiff += distance(tag, GetTagValue(fragUV, vec2<f32>( t,  t)));
    colorDiff += distance(tag, GetTagValue(fragUV, vec2<f32>( t, -t)));
